<body class="viz-root">
<main class="card">
<h1>{{ inputs.data.title }}</h1>
<p class="summary" id="summary"></p>
<div class="plot" id="plot">
<div class="tooltip" id="tooltip" hidden></div>
</div>
<details>
<summary>Show as a table</summary>
<table id="table"><thead><tr><th scope="col">#</th><th scope="col">Value</th></tr></thead><tbody></tbody></table>
</details>
</main>
<script>
const values = {{ inputs.data.values | json_script }};

(function () {
  const SVG = "http://www.w3.org/2000/svg";
  const W = 880, H = 360;
  const M = { top: 12, right: 8, bottom: 28, left: 48 };
  const fmt = new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 });

  function el(name, attrs, parent) {
    const node = document.createElementNS(SVG, name);
    for (const k in attrs) node.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(node);
    return node;
  }

  // A "nice" y-scale that always includes zero, so bars grow from a true baseline.
  function niceTicks(lo, hi, count) {
    if (lo === hi) { hi = lo + 1; }
    const raw = (hi - lo) / count;
    const mag = Math.pow(10, Math.floor(Math.log10(raw)));
    const step = [1, 2, 2.5, 5, 10].map(m => m * mag).find(s => s >= raw);
    const start = Math.floor(lo / step) * step;
    const end = Math.ceil(hi / step) * step;
    const ticks = [];
    for (let v = start; v <= end + step / 2; v += step) ticks.push(+v.toPrecision(12));
    return ticks;
  }

  const min = Math.min(0, ...values), max = Math.max(0, ...values);
  const ticks = niceTicks(min, max, 5);
  const y0 = ticks[0], y1 = ticks[ticks.length - 1];
  const iw = W - M.left - M.right, ih = H - M.top - M.bottom;
  const y = v => M.top + ih - ((v - y0) / (y1 - y0)) * ih;
  const band = iw / values.length;
  const gap = values.length > 1 ? Math.min(2 + band * 0.25, band * 0.5) : band * 0.6;
  const bw = Math.max(band - gap, 1);
  const r = Math.min(4, bw / 2);

  const total = values.reduce((a, b) => a + b, 0);
  document.getElementById("summary").textContent =
    values.length + (values.length === 1 ? " value" : " values") +
    " · min " + fmt.format(Math.min(...values)) +
    " · max " + fmt.format(Math.max(...values)) +
    " · mean " + fmt.format(total / values.length);

  const plot = document.getElementById("plot");
  const tooltip = document.getElementById("tooltip");
  const svg = el("svg", { viewBox: "0 0 " + W + " " + H, role: "img",
    "aria-label": document.querySelector("h1").textContent + ": bar chart of " + values.length + " values" });
  plot.insertBefore(svg, tooltip);

  const grid = el("g", { class: "grid" }, svg);
  for (const t of ticks) {
    if (t !== 0) el("line", { x1: M.left, x2: W - M.right, y1: y(t), y2: y(t) }, grid);
    const label = el("text", { class: "tick", x: M.left - 8, y: y(t), "text-anchor": "end", "dominant-baseline": "middle" }, svg);
    label.textContent = fmt.format(t);
  }

  // X labels: show at most ~12, evenly spaced, 1-based positions.
  const every = Math.max(1, Math.ceil(values.length / 12));
  values.forEach((v, i) => {
    if (i % every !== 0 && i !== values.length - 1) return;
    const label = el("text", { class: "tick", x: M.left + band * (i + 0.5), y: H - M.bottom + 18, "text-anchor": "middle" }, svg);
    label.textContent = i + 1;
  });

  // Bar with 4px rounding on the data end only; the baseline end stays square.
  function barPath(x, w, from, to) {
    const h = Math.abs(to - from);
    const rr = Math.min(r, h);
    if (to <= from) { // grows upward (positive)
      return "M" + x + "," + from + "V" + (to + rr) + "Q" + x + "," + to + " " + (x + rr) + "," + to +
        "H" + (x + w - rr) + "Q" + (x + w) + "," + to + " " + (x + w) + "," + (to + rr) + "V" + from + "Z";
    }
    return "M" + x + "," + from + "V" + (to - rr) + "Q" + x + "," + to + " " + (x + rr) + "," + to +
      "H" + (x + w - rr) + "Q" + (x + w) + "," + to + " " + (x + w) + "," + (to - rr) + "V" + from + "Z";
  }

  const bars = el("g", {}, svg);
  values.forEach((v, i) => {
    const x = M.left + band * i + (band - bw) / 2;
    const hit = el("rect", { class: "hit", x: M.left + band * i, y: M.top, width: band, height: ih }, bars);
    const bar = el("path", { class: "bar", d: barPath(x, bw, y(0), y(v)) }, bars);
    const show = () => {
      bar.classList.add("active");
      tooltip.innerHTML = "";
      const lab = document.createElement("div");
      lab.className = "label";
      lab.textContent = "#" + (i + 1);
      const val = document.createElement("div");
      val.textContent = fmt.format(v);
      tooltip.append(lab, val);
      const box = svg.getBoundingClientRect(), s = box.width / W;
      tooltip.style.left = (M.left + band * (i + 0.5)) * s + "px";
      tooltip.style.top = Math.min(y(v), y(0)) * s + "px";
      tooltip.hidden = false;
    };
    const hide = () => { bar.classList.remove("active"); tooltip.hidden = true; };
    hit.addEventListener("mouseenter", show);
    hit.addEventListener("mouseleave", hide);
  });

  el("line", { class: "baseline", x1: M.left, x2: W - M.right, y1: y(0), y2: y(0) }, svg);

  const tbody = document.querySelector("#table tbody");
  values.forEach((v, i) => {
    const tr = document.createElement("tr");
    const a = document.createElement("td"); a.textContent = i + 1;
    const b = document.createElement("td"); b.textContent = fmt.format(v);
    tr.append(a, b);
    tbody.appendChild(tr);
  });
})();
</script>
</body>
</html>

